compile.workshop:
variables {
    global:
        0: result
    player:
        0: eventTempIndex
}

rule ("unique values") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Filtered Array(Array(1, 2, 1, 3, 2), Compare(Index Of Array Value(Array(1, 2, 1, 3, 2), Current Array Element), ==, Current Array Index)));
    }
}

rule ("Bastion candidate pool") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, eventTempIndex, Filtered Array((Event Player).eventTempIndex, Compare(Index Of Array Value((Event Player).eventTempIndex, Current Array Element), ==, Current Array Index)));
    }
}

